<?php
namespace App\Http\Controllers\POS;
use App\Http\Controllers\Controller; use App\Models\{MenuItem,Outlet,PosOrder,RestaurantTable,Stay}; use App\Services\POS\PosService; use Illuminate\Http\Request; use RuntimeException;
class PosController extends Controller{
 public function index(Request $r){$pid=$r->user()->property_id;$outlets=Outlet::where('property_id',$pid)->where('is_active',true)->orderBy('type')->orderBy('name')->get();$orders=PosOrder::with(['outlet','table','guest'])->where('property_id',$pid)->whereNotIn('status',['paid','cancelled'])->latest('opened_at')->get();$today=PosOrder::where('property_id',$pid)->whereDate('created_at',today());$stats=['open'=>(clone $today)->whereNotIn('status',['paid','cancelled'])->count(),'paid'=>(clone $today)->where('status','paid')->count(),'sales'=>(float)(clone $today)->where('status','paid')->sum('grand_total'),'room_service'=>(clone $today)->where('service_type','room_service')->count()];return view('pos.index',compact('outlets','orders','stats'));}
 public function outlet(Request $r,Outlet $outlet){$this->guard($r,$outlet->property_id);$outlet->load(['tables'=>fn($q)=>$q->where('is_active',true)->orderBy('display_order'),'categories'=>fn($q)=>$q->where('is_active',true)->orderBy('display_order'),'menuItems.modifiers']);$menuItems=MenuItem::with('modifiers')->where('property_id',$outlet->property_id)->where('is_active',true)->where(fn($q)=>$q->where('outlet_id',$outlet->id)->orWhereNull('outlet_id'))->orderBy('name')->get();$stays=Stay::with(['guest','room'])->where('property_id',$outlet->property_id)->where('status','in_house')->orderBy('expected_check_out_at')->get();$orders=PosOrder::with(['table','guest'])->where('outlet_id',$outlet->id)->whereNotIn('status',['paid','cancelled'])->latest()->get();return view('pos.outlet',compact('outlet','menuItems','stays','orders'));}
 public function store(Request $r,Outlet $outlet,PosService $svc){$this->guard($r,$outlet->property_id);$d=$r->validate(['restaurant_table_id'=>'nullable|integer','stay_id'=>'nullable|integer','service_type'=>'required|in:dine_in,takeaway,delivery,room_service','customer_name'=>'nullable|max:150','notes'=>'nullable|max:1000']);$d['outlet_id']=$outlet->id;try{$order=$svc->createOrder($d,$outlet->property_id,$r->user()->id);return redirect()->route('pos.orders.show',$order)->with('success','Order opened successfully.');}catch(RuntimeException $e){return back()->withErrors(['order'=>$e->getMessage()])->withInput();}}
 public function show(Request $r,PosOrder $order,PosService $svc){$this->guard($r,$order->property_id);$order=$svc->recalculate($order);$order->load(['outlet','table','guest','stay.room','items.menuItem.modifiers','items.modifiers','payments','kitchenTicket']);$menuItems=MenuItem::with('modifiers')->where('property_id',$order->property_id)->where('is_active',true)->where(fn($q)=>$q->where('outlet_id',$order->outlet_id)->orWhereNull('outlet_id'))->orderBy('name')->get();return view('pos.order',compact('order','menuItems'));}
 public function addItem(Request $r,PosOrder $order,PosService $svc){$this->guard($r,$order->property_id);$d=$r->validate(['menu_item_id'=>'required|integer','quantity'=>'required|numeric|min:0.001|max:999','modifier_ids'=>'array','modifier_ids.*'=>'integer','notes'=>'nullable|max:500']);$menu=MenuItem::where('property_id',$order->property_id)->findOrFail($d['menu_item_id']);try{$svc->addItem($order,$menu,(float)$d['quantity'],$d['modifier_ids']??[],$d['notes']??null);return back()->with('success','Item added to order.');}catch(RuntimeException $e){return back()->withErrors(['item'=>$e->getMessage()]);}}
 public function sendKitchen(Request $r,PosOrder $order,PosService $svc){$this->guard($r,$order->property_id);$svc->sendToKitchen($order);return back()->with('success','Order sent to kitchen/bar preparation.');}
 public function settle(Request $r,PosOrder $order,PosService $svc){$this->guard($r,$order->property_id);$d=$r->validate(['method'=>'required|in:cash,mtn_momo,airtel_money,pesapal,flutterwave,bank_transfer,card,cheque,room_charge','amount'=>'required|numeric|min:1','payer_phone'=>'nullable|max:50','gateway_reference'=>'nullable|max:120']);try{$svc->settle($order,$d,$r->user()->id);return back()->with('success','Payment applied successfully.');}catch(RuntimeException $e){return back()->withErrors(['payment'=>$e->getMessage()]);}}
 public function receipt(Request $r,PosOrder $order,PosService $svc){$this->guard($r,$order->property_id);$order=$svc->recalculate($order);$order->load(['property','outlet','table','guest','items.modifiers','payments','openedBy']);return view('documents.pos-receipt',compact('order'));}
 private function guard(Request $r,int $propertyId):void{abort_unless($propertyId===$r->user()->property_id,404);}
}
